function parseCookieValue(cookiedata){try{var parsed_data=cookiedata.split(";").map(v=>v.split("=")).reduce((acc,v)=>{acc[decodeURIComponent(v[0].trim())]=decodeURIComponent(v[1].trim())});return parsed_data[1].split(",")}catch(error){return[]}}function onlyUnique(value,index,self){return self.indexOf(value)===index}function CookieList(cookieName,exdays=1){const d=new Date;d.setTime(d.getTime()+exdays*24*60*60*1e3);let expires="expires="+d.toGMTString();var cookie=document.cookie;var items=cookie?parseCookieValue(cookie):[];return{add:function(val){items.push(val);items=items.filter(onlyUnique);document.cookie=cookieName+"="+items.join(",")+";"+expires+";path=/;SameSite=Lax"},remove:function(val){let indx=items.indexOf(val);if(indx!==-1)items.splice(indx,1);items=items.filter(onlyUnique);document.cookie=cookieName+"="+items.join(",")+";"+expires+";path=/;SameSite=Lax"},clear:function(){items=null;document.cookie=cookieName+'=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;";'},items:function(){return items}}}